// Factorial: O(n) time, O(n) stack space
function factorial(n) {
  if (n === 0) return 1;          // base case
  return n * factorial(n - 1);    // recursive case
}

// Naive Fibonacci: O(2^n)
const fibSlow = (n) => (n < 2 ? n : fibSlow(n - 1) + fibSlow(n - 2));

// Memoised Fibonacci: O(n) time, O(n) space
function fib(n, memo = new Map()) {
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n);
  const v = fib(n - 1, memo) + fib(n - 2, memo);
  memo.set(n, v);
  return v;
}

// Reverse a string recursively (indexes, not slices)
function reverse(s, i = s.length - 1) {
  return i < 0 ? '' : s[i] + reverse(s, i - 1);
}

// Power by squaring: O(log n)
function power(x, n) {
  if (n === 0) return 1;
  const half = power(x, Math.floor(n / 2));
  return n % 2 === 0 ? half * half : half * half * x;
}

from functools import lru_cache

# Factorial: O(n) time, O(n) stack space
def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

# Memoised Fibonacci: O(n) time, O(n) space
@lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

# Power by squaring: O(log n)
def power(x, n):
    if n == 0:
        return 1
    half = power(x, n // 2)
    return half * half if n % 2 == 0 else half * half * x

// Memoised Fibonacci: O(n) time, O(n) space
static long fib(int n, long[] memo) {
    if (n < 2) return n;
    if (memo[n] != 0) return memo[n];
    return memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
}

// Power by squaring: O(log n)
static double power(double x, int n) {
    if (n == 0) return 1;
    double half = power(x, n / 2);
    return n % 2 == 0 ? half * half : half * half * x;
}

// Memoised Fibonacci: O(n) time, O(n) space
long long fib(int n, vector<long long>& memo) {
    if (n < 2) return n;
    if (memo[n]) return memo[n];
    return memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
}

// Power by squaring: O(log n)
double power(double x, long long n) {
    if (n == 0) return 1;
    double half = power(x, n / 2);
    return n % 2 == 0 ? half * half : half * half * x;
}

class TreeNode {
  constructor(val, left = null, right = null) { this.val = val; this.left = left; this.right = right; }
}

const inorder = (n, out = []) => { if (n) { inorder(n.left, out); out.push(n.val); inorder(n.right, out); } return out; };
const preorder = (n, out = []) => { if (n) { out.push(n.val); preorder(n.left, out); preorder(n.right, out); } return out; };
const postorder = (n, out = []) => { if (n) { postorder(n.left, out); postorder(n.right, out); out.push(n.val); } return out; };

// Max depth: O(n) time, O(h) space
const maxDepth = (n) => (n ? 1 + Math.max(maxDepth(n.left), maxDepth(n.right)) : 0);

// Invert a tree
function invertTree(n) {
  if (!n) return null;
  [n.left, n.right] = [invertTree(n.right), invertTree(n.left)];
  return n;
}

// Level order with a queue: O(n)
function levelOrder(root) {
  const res = [];
  if (!root) return res;
  let queue = [root];
  while (queue.length) {
    res.push(queue.map((n) => n.val));
    queue = queue.flatMap((n) => [n.left, n.right].filter(Boolean));
  }
  return res;
}

from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def inorder(n, out=None):
    out = [] if out is None else out
    if n:
        inorder(n.left, out); out.append(n.val); inorder(n.right, out)
    return out

# Max depth: O(n) time, O(h) space
def max_depth(n):
    return 1 + max(max_depth(n.left), max_depth(n.right)) if n else 0

# Invert a tree
def invert_tree(n):
    if not n:
        return None
    n.left, n.right = invert_tree(n.right), invert_tree(n.left)
    return n

# Level order with a queue: O(n)
def level_order(root):
    res, q = [], deque([root] if root else [])
    while q:
        level = []
        for _ in range(len(q)):          # fix the level size first
            node = q.popleft()
            level.append(node.val)
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
        res.append(level)
    return res

static class TreeNode { int val; TreeNode left, right; TreeNode(int v) { val = v; } }

static int maxDepth(TreeNode n) {
    return n == null ? 0 : 1 + Math.max(maxDepth(n.left), maxDepth(n.right));
}

static List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) return res;
    Queue<TreeNode> q = new ArrayDeque<>();
    q.add(root);
    while (!q.isEmpty()) {
        int size = q.size(); // fix the level size first
        List<Integer> level = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            TreeNode n = q.poll();
            level.add(n.val);
            if (n.left != null) q.add(n.left);
            if (n.right != null) q.add(n.right);
        }
        res.add(level);
    }
    return res;
}

struct TreeNode { int val; TreeNode *left, *right; TreeNode(int v) : val(v), left(nullptr), right(nullptr) {} };

int maxDepth(TreeNode* n) { return n ? 1 + max(maxDepth(n->left), maxDepth(n->right)) : 0; }

vector<vector<int>> levelOrder(TreeNode* root) {
    vector<vector<int>> res;
    if (!root) return res;
    queue<TreeNode*> q; q.push(root);
    while (!q.empty()) {
        int size = q.size(); // fix the level size first
        vector<int> level;
        for (int i = 0; i < size; i++) {
            TreeNode* n = q.front(); q.pop();
            level.push_back(n->val);
            if (n->left) q.push(n->left);
            if (n->right) q.push(n->right);
        }
        res.push_back(level);
    }
    return res;
}
